   213→      const taskUlids = this.specToTasks.get(specUlid) || [];
   214→      const currentStatus = spec.status?.implementation || "not_started";
   215→      const expectedStatus = this.calculateExpectedStatus(specUlid);
   216→
   217→      // Orphaned spec (no tasks)
   218→      // AC: @trait-retrospective ac-1
   219→      // Skip retrospective specs from orphaned warnings
   220→      // Policy: warn for not_started and in_progress (suspicious), but trust
   221→      // implemented/verified as baseline history predating the task system.
   222→      const isRetrospective = spec.traits?.includes("@trait-retrospective");
   223→      if (
   224→        taskUlids.length === 0 &&
   225→        (currentStatus === "not_started" || currentStatus === "in_progress") &&
   226→        !isRetrospective
   227→      ) {
   228→        warnings.push({
   229→          type: "orphaned_spec",
   230→          specUlid,
   231→          specTitle: spec.title,
   232→          message: `Spec item "${spec.title}" has no implementing tasks`,
   233→        });
   234→      }
   235→
   236→      // Status mismatch (only when tasks exist — no-task specs are handled above
   237→      // for not_started/in_progress; implemented/verified are trusted as baseline)
   238→      if (taskUlids.length > 0 && currentStatus !== expectedStatus) {
   239→        warnings.push({
   240→          type: "status_mismatch",
   241→          specUlid,
   242→          specTitle: spec.title,
   243→          message: `Spec "${spec.title}" status is "${currentStatus}" but should be "${expectedStatus}" based on task progress`,
   244→        });
   245→      }
   246→    }
   247→
   248→    // Check completed tasks with stale spec status
   249→    for (const [taskUlid, task] of this.tasks) {
   250→      if (task.status === "completed" && task.spec_ref) {
   251→        const specRef = this.taskToSpec.get(taskUlid);
   252→        if (specRef) {
   253→          // Note: We already checked this via spec iteration above
   254→          // But this provides task-centric context
   255→        }
   256→      }
   257→    }
   258→
   259→    return warnings;
   260→  }
   261→
   262→  /**
   263→   * Get all spec items with their implementation summary
   264→   */
   265→  getAllImplementationSummaries(): SpecImplementationSummary[] {
   266→    const summaries: SpecImplementationSummary[] = [];
   267→    for (const specUlid of this.specItems.keys()) {
   268→      const summary = this.getImplementationSummary(specUlid);
   269→      if (summary) {
   270→        summaries.push(summary);
   271→      }
   272→    }
   273→    return summaries;
   274→  }
   275→
   276→  /**
   277→   * Get stats about alignment
   278→   */
   279→  getStats(): {
   280→    totalSpecs: number;
   281→    specsWithTasks: number;
   282→    alignedSpecs: number;
   283→    orphanedSpecs: number;
   284→  } {
   285→    let specsWithTasks = 0;
   286→    let alignedSpecs = 0;
   287→    let orphanedSpecs = 0;
   288→
   289→    for (const specUlid of this.specItems.keys()) {
   290→      const taskUlids = this.specToTasks.get(specUlid) || [];
   291→      if (taskUlids.length > 0) {
   292→        specsWithTasks++;
   293→        const summary = this.getImplementationSummary(specUlid);
   294→        if (summary?.isAligned) {
   295→          alignedSpecs++;
   296→        }
   297→      } else {
   298→        orphanedSpecs++;
   299→      }
   300→    }
   301→
   302→    return {
   303→      totalSpecs: this.specItems.size,
   304→      specsWithTasks,
   305→      alignedSpecs,
   306→      orphanedSpecs,
   307→    };
   308→  }
   309→}
   310→
   311→// ============================================================
   312→// SYNC FUNCTIONS
   313→// ============================================================
   314→
   315→/**
   316→ * Result of syncing spec implementation status
   317→ */
   318→export interface SyncResult {
   319→  synced: boolean;
   320→  specUlid: string;
   321→  specTitle: string;
   322→  previousStatus: ImplementationStatus;
   323→  newStatus: ImplementationStatus;
   324→}
   325→
   326→/**
   327→ * Sync a spec item's implementation status based on its linked tasks.
   328→ * Called after task state changes (start, complete, etc.).
   329→ *
   330→ * @returns SyncResult if status changed, null if no change needed or no spec_ref
   331→ */
   332→export async function syncSpecImplementationStatus(
   333→  ctx: KspecContext,
   334→  task: LoadedTask,
   335→  allTasks: LoadedTask[],
   336→  allItems: LoadedSpecItem[],
   337→  refIndex: ReferenceIndex,
   338→): Promise<SyncResult | null> {
   339→  // Skip if task has no spec_ref
   340→  if (!task.spec_ref) {
   341→    return null;
   342→  }
   343→
   344→  // Resolve the spec reference
   345→  const result = refIndex.resolve(task.spec_ref);
   346→  if (!result.ok) {
   347→    return null;
   348→  }
   349→
   350→  // Find the spec item
   351→  const specItem = allItems.find((item) => item._ulid === result.ulid);
   352→  if (!specItem) {
   353→    return null;
   354→  }
   355→
   356→  // Build alignment index to calculate expected status
   357→  const alignmentIndex = new AlignmentIndex(allTasks, allItems);
   358→  alignmentIndex.buildLinks(refIndex);
   359→
   360→  const expectedStatus = alignmentIndex.calculateExpectedStatus(specItem._ulid);
   361→  const currentStatus = specItem.status?.implementation || "not_started";
   362→
   363→  // No change needed
   364→  if (currentStatus === expectedStatus) {
   365→    return null;
   366→  }
   367→
   368→  // Update the spec item
   369→  await updateSpecItem(ctx, specItem, {
   370→    status: {
   371→      maturity: specItem.status?.maturity || "draft",
   372→      implementation: expectedStatus,
   373→    },
   374→  });
   375→
   376→  return {
   377→    synced: true,
   378→    specUlid: specItem._ulid,
