const { initContext, loadAllTasks, loadAllItems, ReferenceIndex, AlignmentIndex } = require('./dist/parser/index.js');

(async () => {
  const ctx = await initContext();
  const tasks = await loadAllTasks(ctx);
  const items = await loadAllItems(ctx);
  const refIndex = new ReferenceIndex(tasks, items);
  const alignmentIndex = new AlignmentIndex(tasks, items);
  alignmentIndex.buildLinks(refIndex);

  // Find the ui-plans-view spec
  const plansSpec = items.find(i => i.slugs && i.slugs.includes('ui-plans-view'));
  if (plansSpec) {
    console.log('Spec ULID:', plansSpec._ulid);
    console.log('Spec status:', plansSpec.status?.implementation);
  } else {
    console.log('Spec not found');
    process.exit(1);
  }

  // Find the task
  const task = tasks.find(t => t.spec_ref === '@ui-plans-view');
  if (task) {
    console.log('Task ULID:', task._ulid);
    console.log('Task status:', task.status);
    console.log('Task spec_ref:', task.spec_ref);
  } else {
    console.log('No task with spec_ref @ui-plans-view');
    const plansTask = tasks.find(t => t.title.includes('Plans View'));
    if (plansTask) {
      console.log('Found by title - ULID:', plansTask._ulid, 'spec_ref:', plansTask.spec_ref, 'status:', plansTask.status);
    }
  }

  const summary = alignmentIndex.getImplementationSummary(plansSpec._ulid);
  console.log('Expected status:', summary?.expectedStatus);
  console.log('Is aligned:', summary?.isAligned);
  console.log('Linked tasks:', summary?.linkedTasks?.length);
  if (summary?.linkedTasks) {
    summary.linkedTasks.forEach(t => console.log('  -', t.taskUlid, t.taskStatus, t.taskTitle));
  }

  // Also check ref resolution
  const refResult = refIndex.resolve('@ui-plans-view');
  console.log('Ref resolve @ui-plans-view:', JSON.stringify(refResult));
})();

